package com.example.social.service;
import com.example.social.config.JwtService; import com.example.social.repository.UserRepository; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.Map;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}public Map<String,Object> login(String email,String password){var user=users.findByEmail(email).orElseThrow(()->new IllegalArgumentException("Invalid email or password"));if(!encoder.matches(password,user.getPassword()))throw new IllegalArgumentException("Invalid email or password");return Map.of("token",jwt.generate(email,user.getRole()),"email",email,"name",user.getName(),"role",user.getRole());}}
